**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    int n = tab.size();

    int currSum = 0, maxSum = tab[0];
    int tempStart = 0, bestStart = 0, bestEnd = 0;

    for (int i = 0; i < n; i++) {
        currSum += tab[i];
        if (currSum > maxSum) {
            maxSum = currSum;
            bestStart = tempStart;
            bestEnd = i;
        }
        if (currSum < 0) {
            currSum = 0;
            tempStart = i + 1;
        }
    }

    cout << "a) Maksymalna suma podciagu: " << maxSum << endl;
    cout << "b) Pozycja: od " << bestStart + 1 << " do " << bestEnd + 1 << endl;
    cout << "c) Elementy:";
    for (int i = bestStart; i <= bestEnd; i++) cout << " " << tab[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm Kadane'a w O(n): sledzmy biezaca sume — jesli staje sie ujemna, resetujemy (lepiej zaczac od nowa). Sledzmy tez najlepsza sume i odpowiadajacy podciag.

Weryfikacja:
- currSum po kazdym kroku: -2(reset), 3, 2, 7, 3, 9, 6, 8, 16, 9, 13, 12
- maxSum aktualizacje: -2 -> 3 -> 7 -> 9 -> 16
- Najlepszy podciag: pozycje 2-9 (1-ind.), elementy: 3,-1,5,-4,6,-3,2,8
- Suma: 3+(-1)+5+(-4)+6+(-3)+2+8 = 16
